import React, { useState } from 'react';
import { Toaster } from 'react-hot-toast';
import { AppProvider } from './context/AppContext';
import TablesView from './components/TablesView';
import KitchenView from './components/KitchenView';
import HistoryView from './components/HistoryView';
import StaffView from './components/StaffView';

const NAV_ITEMS = [
  { id: 'tables', label: 'Tables', icon: '🍽️' },
  { id: 'kitchen', label: 'Kitchen', icon: '👨‍🍳' },
  { id: 'history', label: 'Analytics', icon: '📊' },
  { id: 'staff', label: 'Staff', icon: '👥' },
];

function Layout() {
  const [active, setActive] = useState('tables');

  const views = {
    tables: <TablesView />,
    kitchen: <KitchenView />,
    history: <HistoryView />,
    staff: <StaffView />,
  };

  return (
    <div className="min-h-screen bg-gray-950 flex">
      {/* Sidebar */}
      <aside className="w-56 bg-gray-900 border-r border-gray-800 flex flex-col">
        <div className="p-5 border-b border-gray-800">
          <h1 className="text-xl font-bold text-white">BitePlate</h1>
          <p className="text-xs text-gray-500 mt-1">Smart Restaurant System</p>
        </div>
        <nav className="flex-1 p-3">
          {NAV_ITEMS.map((item) => (
            <button
              key={item.id}
              onClick={() => setActive(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-left mb-1 transition-colors ${
                active === item.id
                  ? 'bg-indigo-600 text-white'
                  : 'text-gray-400 hover:bg-gray-800 hover:text-white'
              }`}
            >
              <span>{item.icon}</span>
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-gray-800">
          <p className="text-xs text-gray-600">Unit 27 — BTEC L5</p>
          <p className="text-xs text-gray-700">OOP & Design Patterns</p>
        </div>
      </aside>

      {/* Main content */}
      <main className="flex-1 p-8 overflow-y-auto">
        {views[active]}
      </main>
    </div>
  );
}

export default function App() {
  return (
    <AppProvider>
      <Toaster
        position="top-right"
        toastOptions={{
          style: { background: '#1e293b', color: '#f1f5f9', border: '1px solid #334155' },
        }}
      />
      <Layout />
    </AppProvider>
  );
}
